typescript_types.WilayahItem:
export interface WilayahItem {
  kode: string;
  nama: string;
  kodepos?: string | null;
}

typescript_types.WilayahSearchResult:
export interface WilayahSearchResult extends WilayahItem {
  path: WilayahItem[];
}

typescript_types.QuickSearchResult:
export interface QuickSearchResult extends WilayahItem {
  level: 3 | 4;
  path: WilayahItem[];
}

code_snippets.javascript_fetch:
const BASE_URL = 'https://wil.nri.my.id';

// 1. Ambil Provinsi
const provinces = await fetch(`${BASE_URL}/api/wilayah`).then(r => r.json());

// 2. Ambil Anak Wilayah
const regencies = await fetch(`${BASE_URL}/api/wilayah?parent=32`).then(r => r.json());

// 3. Quick Search (Nama / Kode Pos)
const search = await fetch(`${BASE_URL}/api/wilayah/quick-search?q=sukamaju`).then(r => r.json());
